#!/usr/bin/env bash
# One-file installer for Rubika Copier. The app source is the base64 payload below.
# Build with scripts/build-rubika-install.sh. Do not fetch code from the network.
set -euo pipefail

BUILD_ID="86706d2"
PAYLOAD=''

APP_DIR=/opt/rubika-copier
DATA_DIR=/var/lib/rubika-copier
ENV_FILE=/etc/rubika-copier.env
CREDS_FILE=/etc/rubika-copier.credentials
UNIT_DEST=/etc/systemd/system/rubika-copier.service
BACKUP_ROOT=/root/rubika-backups
LOG=/var/log/rubika-copier-install.log
SWAP_FILE=/swapfile-rubika
FSTAB=/etc/fstab
SERVICE_NAME=rubika-copier

ACTION=""
PURGE=0
PORT="8741"
PORT_SET=0
PANEL_USER=""
USER_SET=0
PANEL_PASS=""
PASS_SET=0
SWAP_SIZE=""
RESTORE_FILE=""
STOPPED=0
GENERATED_PASS=0

usage() {
  cat <<'EOF'
استفاده:
  bash rubika-install.sh                 منوی فارسی
  bash rubika-install.sh --install       نصب بدون پرسش
  bash rubika-install.sh --update        به‌روزرسانی؛ اول پشتیبان، داده دست نمی‌خورد
  bash rubika-install.sh --backup        پشتیبان پایگاه، env، واحد و پروفایل
  bash rubika-install.sh --restore FILE  بازیابی بعد از تطبیق SHA256
  bash rubika-install.sh --status        سرویس، حافظه، صف، نشست‌ها
  bash rubika-install.sh --info          نشانی پنل، نام کاربری و رمز
  bash rubika-install.sh --reset-login   عوض کردن نام کاربری و رمز پنل
  bash rubika-install.sh --uninstall     حذف سرویس و کد؛ داده می‌ماند
  bash rubika-install.sh --uninstall --purge
                                         حذف داده هم، با نوشتن «حذف داده»

گزینه‌ها:
  --port N     درگاه پنل (پیش‌فرض ۸۷۴۱)
  --user U     نام کاربری پنل (پیش‌فرض mehran)
  --pass P     رمز پنل (اگر ندهید رمز تصادفی ساخته می‌شود)
  --swap SIZE  اندازه سواپ، مثل 2G یا 512M
EOF
}

say() {
  printf '%s\n' "$*"
  if [[ -n "${LOG:-}" ]]; then
    printf '%s\n' "$*" >>"$LOG" 2>/dev/null || true
  fi
}

die() {
  printf 'خطا: %s\n' "$*" >&2
  if [[ -n "${LOG:-}" ]]; then
    printf 'خطا: %s\n' "$*" >>"$LOG" 2>/dev/null || true
  fi
  if [[ "$STOPPED" -eq 1 ]]; then
    printf 'خطا: سرویس متوقف مانده است. بعد از رفع مشکل: systemctl start %s\n' "$SERVICE_NAME" >&2
  fi
  exit 1
}

# Reachable from the ERR trap in prepare_log.
# shellcheck disable=SC2317
on_err() {
  local code=$?
  printf 'خطا: دستور ناموفق بود (کد %s). گزارش در %s\n' "$code" "${LOG:-/var/log/rubika-copier-install.log}" >&2
  if [[ "$STOPPED" -eq 1 ]]; then
    printf 'خطا: سرویس متوقف مانده است. بعد از رفع مشکل: systemctl start %s\n' "$SERVICE_NAME" >&2
  fi
  exit "$code"
}

is_test() {
  [[ "${RUBIKA_INSTALL_TEST:-}" == "1" ]]
}

apply_test_paths() {
  local prefix="${RUBIKA_INSTALL_PREFIX:-}"
  if [[ -z "$prefix" ]]; then
    die "در حالت آزمایش RUBIKA_INSTALL_PREFIX لازم است"
  fi
  APP_DIR="$prefix/opt/rubika-copier"
  DATA_DIR="$prefix/var/lib/rubika-copier"
  ENV_FILE="$prefix/etc/rubika-copier.env"
  CREDS_FILE="$prefix/etc/rubika-copier.credentials"
  UNIT_DEST="$prefix/etc/systemd/system/rubika-copier.service"
  BACKUP_ROOT="$prefix/root/rubika-backups"
  LOG="$prefix/var/log/rubika-copier-install.log"
  SWAP_FILE="$prefix/swapfile-rubika"
  FSTAB="$prefix/etc/fstab"
  mkdir -p "$(dirname "$UNIT_DEST")" "$(dirname "$ENV_FILE")" "$(dirname "$FSTAB")" "$BACKUP_ROOT"
  if [[ ! -f "$prefix/service.state" ]]; then
    printf '%s\n' inactive >"$prefix/service.state"
  fi
}

prepare_log() {
  mkdir -p "$(dirname "$LOG")"
  touch "$LOG"
  chmod 600 "$LOG" || true
  trap on_err ERR
}

require_root() {
  if is_test; then
    return 0
  fi
  if [[ "$(id -u)" -ne 0 ]]; then
    die "این دستور باید با root اجرا شود"
  fi
}

parse_args() {
  while [[ $# -gt 0 ]]; do
    case "$1" in
      --install) ACTION=install ;;
      --update) ACTION=update ;;
      --backup) ACTION=backup ;;
      --restore)
        ACTION=restore
        if [[ $# -lt 2 || "$2" == --* ]]; then
          die "مسیر فایل پشتیبان را بعد از --restore بنویسید"
        fi
        RESTORE_FILE="$2"
        shift
        ;;
      --status) ACTION=status ;;
      --info) ACTION=info ;;
      --reset-login) ACTION=reset ;;
      --uninstall) ACTION=uninstall ;;
      --purge) PURGE=1 ;;
      --port)
        if [[ $# -lt 2 ]]; then
          die "شماره درگاه بعد از --port لازم است"
        fi
        PORT="$2"
        PORT_SET=1
        shift
        ;;
      --user)
        if [[ $# -lt 2 || -z "$2" ]]; then
          die "نام کاربری بعد از --user لازم است"
        fi
        PANEL_USER="$2"
        USER_SET=1
        shift
        ;;
      --pass)
        if [[ $# -lt 2 || -z "$2" ]]; then
          die "رمز بعد از --pass لازم است"
        fi
        PANEL_PASS="$2"
        PASS_SET=1
        shift
        ;;
      --swap)
        if [[ $# -lt 2 || -z "$2" ]]; then
          die "اندازه سواپ بعد از --swap لازم است"
        fi
        SWAP_SIZE="$2"
        shift
        ;;
      -h|--help)
        usage
        exit 0
        ;;
      *)
        die "گزینه ناشناخته است: $1"
        ;;
    esac
    shift
  done
  if [[ "$PURGE" -eq 1 && "$ACTION" != uninstall ]]; then
    die "گزینه --purge فقط همراه --uninstall است"
  fi
  if [[ ! "$PORT" =~ ^[0-9]+$ ]] || [[ "$PORT" -lt 1 || "$PORT" -gt 65535 ]]; then
    die "درگاه نامعتبر است: $PORT"
  fi
}

check_os() {
  if is_test; then
    return 0
  fi
  local id="" version=""
  if [[ -r /etc/os-release ]]; then
    # shellcheck disable=SC1091
    . /etc/os-release
    id="${ID:-}"
    version="${VERSION_ID:-}"
  fi
  case "${id}-${version}" in
    ubuntu-22.04|ubuntu-24.04|debian-12) ;;
    *)
      die "این نصب برای اوبونتو ۲۲.۰۴ و ۲۴.۰۴ و دبیان ۱۲ است. سیستم فعلی: ${id:-ناشناخته} ${version:-}"
      ;;
  esac
}

svc() {
  if is_test; then
    local prefix="${RUBIKA_INSTALL_PREFIX}"
    printf '%s\n' "$*" >>"$prefix/systemctl.actions"
    case "$1" in
      start|restart)
        printf '%s\n' active >"$prefix/service.state"
        ;;
      stop)
        printf '%s\n' inactive >"$prefix/service.state"
        STOPPED=1
        ;;
      enable)
        printf '%s\n' enabled >"$prefix/service.enabled"
        ;;
      disable)
        printf '%s\n' disabled >"$prefix/service.enabled"
        ;;
      is-active)
        cat "$prefix/service.state" 2>/dev/null || printf '%s\n' inactive
        return 0
        ;;
      is-enabled)
        cat "$prefix/service.enabled" 2>/dev/null || printf '%s\n' disabled
        return 0
        ;;
      daemon-reload) ;;
      *) ;;
    esac
    return 0
  fi
  systemctl "$@"
}

stop_service() {
  if is_test; then
    svc stop "$SERVICE_NAME" || true
    return 0
  fi
  if systemctl list-unit-files "$SERVICE_NAME.service" --no-legend 2>/dev/null | grep -q "$SERVICE_NAME"; then
    systemctl stop "$SERVICE_NAME" || true
    STOPPED=1
  fi
}

start_service() {
  svc daemon-reload
  svc enable "$SERVICE_NAME"
  svc restart "$SERVICE_NAME"
  STOPPED=0
}

env_get() {
  local key="$1"
  python3 - "$ENV_FILE" "$key" <<'PY'
import sys
path, key = sys.argv[1], sys.argv[2]
try:
    lines = open(path, encoding="utf-8")
except FileNotFoundError:
    sys.exit(0)
for raw in lines:
    line = raw.strip()
    if not line or line.startswith("#") or "=" not in line:
        continue
    name, value = line.split("=", 1)
    if name == key:
        print(value.strip().strip('"').replace('\\"', '"').replace("\\\\", "\\"))
        break
PY
}

write_env() {
  RUBIKA_HOME="$DATA_DIR" \
  RUBIKA_PORT="$PORT" \
  RUBIKA_PANEL_USER="$PANEL_USER" \
  RUBIKA_PANEL_PASSWORD="$PANEL_PASS" \
  RUBIKA_BROWSERS="$APP_DIR/ms-playwright" \
  python3 - "$ENV_FILE" <<'PY'
import os
import sys
path = sys.argv[1]
updates = {
    "RUBIKA_COPIER_HOME": os.environ["RUBIKA_HOME"],
    "RUBIKA_COPIER_HOST": "0.0.0.0",
    "RUBIKA_COPIER_PORT": os.environ["RUBIKA_PORT"],
    "RUBIKA_COPIER_HEADLESS": "1",
    "RUBIKA_COPIER_BROWSER": "chrome",
    "RUBIKA_COPIER_PANEL_USER": os.environ["RUBIKA_PANEL_USER"],
    "RUBIKA_COPIER_PANEL_PASSWORD": os.environ["RUBIKA_PANEL_PASSWORD"],
    "PLAYWRIGHT_BROWSERS_PATH": os.environ["RUBIKA_BROWSERS"],
}

def quote(value: str) -> str:
    if "\n" in value or "\x00" in value:
        raise SystemExit("مقدار رمز یا نام کاربری خط جدید دارد")
    escaped = value.replace("\\", "\\\\").replace('"', '\\"')
    return f'"{escaped}"'

seen = set()
out = []
if os.path.exists(path):
    for raw in open(path, encoding="utf-8"):
        line = raw.rstrip("\n")
        stripped = line.strip()
        if not stripped or stripped.startswith("#") or "=" not in stripped:
            out.append(line)
            continue
        name = stripped.split("=", 1)[0]
        if name in updates:
            out.append(f"{name}={quote(updates[name])}")
            seen.add(name)
        else:
            out.append(line)
for name, value in updates.items():
    if name not in seen:
        out.append(f"{name}={quote(value)}")
text = "\n".join(out) + "\n"
os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
with open(path, "w", encoding="utf-8") as handle:
    handle.write(text)
os.chmod(path, 0o600)
PY
}

public_ip() {
  if is_test; then
    printf '%s\n' "203.0.113.10"
    return 0
  fi
  local ip=""
  ip="$(curl -4 -fsS --max-time 4 https://api.ipify.org 2>/dev/null || true)"
  if [[ ! "$ip" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
    ip="$(hostname -I 2>/dev/null | awk '{print $1}')"
  fi
  if [[ -z "$ip" ]]; then
    ip="127.0.0.1"
  fi
  printf '%s\n' "$ip"
}

write_credentials() {
  local ip url
  ip="$(public_ip)"
  url="http://${ip}:${PORT}/"
  python3 - "$CREDS_FILE" "$url" "$PANEL_USER" "$PANEL_PASS" <<'PY'
import os
import sys
path, url, user, password = sys.argv[1:]
os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
with open(path, "w", encoding="utf-8") as handle:
    handle.write(f"url={url}\nuser={user}\npassword={password}\n")
os.chmod(path, 0o600)
PY
  printf 'پنل: %s\n' "$url"
  printf 'نام کاربری: %s\n' "$PANEL_USER"
  printf 'رمز: %s\n' "$PANEL_PASS"
  if [[ "$GENERATED_PASS" -eq 1 ]]; then
    say "رمز تصادفی ساخته شد."
  fi
  say "نام کاربری در ${CREDS_FILE} است. رمز فقط روی صفحه و در همان فایل است."
  say "گام بعد: ورود تلگرام و روبیکا دستی است. پنل را باز کنید، QR تلگرام را اسکن کنید و شماره روبیکا را وارد کنید."
}

read_credentials() {
  python3 - "$CREDS_FILE" <<'PY'
import sys
path = sys.argv[1]
found = {}
try:
    lines = open(path, encoding="utf-8")
except FileNotFoundError:
    sys.exit(2)
for raw in lines:
    line = raw.rstrip("\n")
    if "=" not in line:
        continue
    name, value = line.split("=", 1)
    found[name] = value
print(found.get("url", ""))
print(found.get("user", ""))
print(found.get("password", ""))
PY
}

resolve_identity() {
  local existing_user="" existing_pass="" existing_port=""
  existing_user="$(env_get RUBIKA_COPIER_PANEL_USER || true)"
  existing_pass="$(env_get RUBIKA_COPIER_PANEL_PASSWORD || true)"
  existing_port="$(env_get RUBIKA_COPIER_PORT || true)"
  if [[ "$PORT_SET" -eq 0 && "$existing_port" =~ ^[0-9]+$ ]]; then
    PORT="$existing_port"
  fi
  if [[ "$USER_SET" -eq 0 ]]; then
    if [[ -n "$existing_user" ]]; then
      PANEL_USER="$existing_user"
    else
      PANEL_USER="mehran"
    fi
  fi
  if [[ "$PASS_SET" -eq 0 ]]; then
    if [[ "$ACTION" == reset ]]; then
      PANEL_PASS=""
    elif [[ -n "$existing_pass" ]]; then
      PANEL_PASS="$existing_pass"
    fi
  fi
  if [[ -z "$PANEL_PASS" ]]; then
    PANEL_PASS="$(python3 -c 'import secrets; print(secrets.token_urlsafe(18))')"
    GENERATED_PASS=1
  fi
}

prompt_reset() {
  local typed_user="" typed_pass=""
  if [[ "$USER_SET" -eq 1 && "$PASS_SET" -eq 1 ]]; then
    return 0
  fi
  if [[ -t 0 ]]; then
    if [[ "$USER_SET" -eq 0 ]]; then
      read -r -p "نام کاربری پنل (خالی یعنی ${PANEL_USER}): " typed_user || true
      if [[ -n "$typed_user" ]]; then
        PANEL_USER="$typed_user"
      fi
    fi
    if [[ "$PASS_SET" -eq 0 ]]; then
      read -r -s -p "رمز جدید (خالی یعنی ساخت رمز تصادفی): " typed_pass || true
      printf '\n'
      if [[ -n "$typed_pass" ]]; then
        PANEL_PASS="$typed_pass"
        GENERATED_PASS=0
      fi
    fi
  fi
}

extract_source() {
  local dest="$1"
  mkdir -p "$dest"
  if [[ -z "$PAYLOAD" ]]; then
    die "بسته سورس داخل نصب‌کننده خالی است. فایل را دوباره بسازید"
  fi
  printf '%s' "$PAYLOAD" | base64 -d | tar -xzf - -C "$dest"
}

install_code() {
  local stage="$1"
  [[ -d "$stage/rubika_copier" && -f "$stage/pyproject.toml" ]] || die "بسته سورس ناقص است"
  mkdir -p "$APP_DIR"
  local name
  for name in rubika_copier systemd scripts docs; do
    rm -rf "${APP_DIR:?}/$name"
    if [[ -d "$stage/$name" ]]; then
      cp -a "$stage/$name" "$APP_DIR/$name"
    fi
  done
  for name in pyproject.toml requirements.txt README.md INSTALL.md; do
    if [[ -f "$stage/$name" ]]; then
      cp -a "$stage/$name" "$APP_DIR/$name"
    fi
  done
  if ! grep -q 'Restart=always' "$APP_DIR/systemd/rubika-copier.service"; then
    die "واحد systemd گزینه Restart=always ندارد"
  fi
}

install_python() {
  if is_test; then
    mkdir -p "$APP_DIR/.venv/bin" "$APP_DIR/ms-playwright"
    printf '%s\n' '#!/bin/sh' 'exit 0' >"$APP_DIR/.venv/bin/rubika-copier"
    chmod 755 "$APP_DIR/.venv/bin/rubika-copier"
    printf '%s\n' force-reinstall >>"${RUBIKA_INSTALL_PREFIX}/pip.actions"
    return 0
  fi
  export DEBIAN_FRONTEND=noninteractive
  apt-get update -qq
  apt-get install -y -qq python3 python3-venv python3-pip ca-certificates curl tar gzip \
    fonts-noto-core findutils coreutils
  if [[ ! -x "$APP_DIR/.venv/bin/pip" ]]; then
    python3 -m venv "$APP_DIR/.venv"
  fi
  "$APP_DIR/.venv/bin/pip" install --upgrade pip
  "$APP_DIR/.venv/bin/pip" install --force-reinstall "$APP_DIR"
  mkdir -p "$APP_DIR/ms-playwright"
  PLAYWRIGHT_BROWSERS_PATH="$APP_DIR/ms-playwright" \
    "$APP_DIR/.venv/bin/python" -m playwright install-deps chromium
  PLAYWRIGHT_BROWSERS_PATH="$APP_DIR/ms-playwright" \
    "$APP_DIR/.venv/bin/python" -m playwright install chromium
}

ensure_user() {
  mkdir -p "$DATA_DIR/profiles/telegram" "$DATA_DIR/profiles/rubika" "$DATA_DIR/downloads"
  if is_test; then
    return 0
  fi
  if ! id rubikacopier >/dev/null 2>&1; then
    useradd --system --create-home --home-dir "$DATA_DIR" --shell /usr/sbin/nologin rubikacopier
  fi
  chown -R rubikacopier:rubikacopier "$DATA_DIR" "$APP_DIR"
}

install_unit() {
  mkdir -p "$(dirname "$UNIT_DEST")"
  cp -a "$APP_DIR/systemd/rubika-copier.service" "$UNIT_DEST"
  chmod 644 "$UNIT_DEST"
}

clear_singleton_locks() {
  local root="$DATA_DIR/profiles" removed
  [[ -d "$root" ]] || return 0
  removed="$(find "$root" -name 'Singleton*' -xtype l -print -delete || true)"
  if [[ -n "$removed" ]]; then
    say "قفل شکسته کروم برداشته شد تا به‌روزرسانی متوقف نشود."
    printf '%s\n' "$removed" >>"$LOG"
  fi
}

swap_spec_ok() {
  local spec="${1^^}"
  [[ "$spec" =~ ^[0-9]+[MG]$ ]]
}

ensure_swap() {
  local mem_kb swap_kb mem_mb spec plan="none"
  mem_kb="${RUBIKA_INSTALL_FAKE_MEM_KB:-$(awk '/MemTotal:/ {print $2}' /proc/meminfo)}"
  swap_kb="${RUBIKA_INSTALL_FAKE_SWAP_KB:-$(awk '/SwapTotal:/ {print $2}' /proc/meminfo)}"
  mem_mb=$((mem_kb / 1024))
  if [[ "$mem_mb" -lt 2048 ]]; then
    say "هشدار: حافظه کمتر از ۲ گیگابایت است (${mem_mb} مگابایت). ویدیو ممکن است کند یا گیر کند."
  fi
  if [[ -n "$SWAP_SIZE" ]]; then
    if ! swap_spec_ok "$SWAP_SIZE"; then
      die "اندازه سواپ نامعتبر است. نمونه: 2G یا 512M"
    fi
    spec="${SWAP_SIZE^^}"
    plan="$spec"
  elif [[ "$mem_mb" -lt 3072 && "$swap_kb" -eq 0 ]]; then
    spec="2G"
    plan="2G"
  fi
  say "SWAP_PLAN=${plan}"
  if [[ "$plan" == none ]]; then
    return 0
  fi
  if is_test; then
    printf '%s\n' "$plan" >"${RUBIKA_INSTALL_PREFIX}/swap.planned"
    return 0
  fi
  if swapon --show=NAME --noheadings 2>/dev/null | grep -Fxq "$SWAP_FILE"; then
    say "فایل سواپ از قبل فعال است."
    return 0
  fi
  if [[ ! -f "$SWAP_FILE" ]]; then
    if ! fallocate -l "$spec" "$SWAP_FILE"; then
      local megs=0
      case "$spec" in
        *G) megs=$((${spec%G} * 1024)) ;;
        *M) megs=$((${spec%M})) ;;
      esac
      dd if=/dev/zero of="$SWAP_FILE" bs=1M count="$megs" status=none
    fi
    chmod 600 "$SWAP_FILE"
    mkswap "$SWAP_FILE" >/dev/null
  fi
  swapon "$SWAP_FILE"
  if [[ -f "$FSTAB" ]] && grep -Fqx "$SWAP_FILE none swap sw 0 0" "$FSTAB"; then
    return 0
  fi
  printf '%s\n' "$SWAP_FILE none swap sw 0 0" >>"$FSTAB"
  say "سواپ ${spec} فعال شد."
}

allow_port() {
  if is_test; then
    return 0
  fi
  if command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -q 'Status: active'; then
    ufw allow "${PORT}/tcp" || true
    say "درگاه ${PORT} در فایروال باز شد."
  fi
}

installed_marker() {
  [[ -d "$APP_DIR/rubika_copier" && -f "$ENV_FILE" ]]
}

load_port() {
  local existing=""
  if [[ "$PORT_SET" -eq 1 ]]; then
    return 0
  fi
  existing="$(env_get RUBIKA_COPIER_PORT || true)"
  if [[ "$existing" =~ ^[0-9]+$ ]]; then
    PORT="$existing"
  fi
}

cmd_install() {
  local stage
  check_os
  require_root
  say "نصب روبیکا کپی‌یار، ساخت ${BUILD_ID}."
  ensure_swap
  stop_service
  clear_singleton_locks
  stage="$(mktemp -d)"
  extract_source "$stage"
  install_code "$stage"
  rm -rf "$stage"
  install_python
  ensure_user
  resolve_identity
  write_env
  install_unit
  allow_port
  start_service
  write_credentials
  say "نصب تمام شد."
}

cmd_update() {
  local stage
  check_os
  require_root
  if ! installed_marker; then
    die "نصبی پیدا نشد. اول bash rubika-install.sh --install را بزنید"
  fi
  say "به‌روزرسانی شروع شد. اول پشتیبان گرفته می‌شود."
  ensure_swap
  stop_service
  clear_singleton_locks
  cmd_backup_body
  stage="$(mktemp -d)"
  extract_source "$stage"
  install_code "$stage"
  rm -rf "$stage"
  install_python
  ensure_user
  resolve_identity
  write_env
  install_unit
  start_service
  write_credentials
  say "به‌روزرسانی تمام شد. پایگاه، نشست و پروفایل کروم ماندند."
}

backup_stamp() {
  date -u +%Y%m%dT%H%M%SZ
}

cmd_backup_body() {
  local stamp dest stage archive name
  require_root
  clear_singleton_locks
  stamp="$(backup_stamp)"
  dest="${BACKUP_ROOT}/${stamp}"
  stage="$(mktemp -d)"
  mkdir -p "$dest" "$stage/env" "$stage/unit" "$stage/profiles"
  for name in copier.db copier.db-wal copier.db-shm registry.db registry.db-wal registry.db-shm whatsapp.db whatsapp.db-wal whatsapp.db-shm; do
    if [[ -f "$DATA_DIR/$name" ]]; then
      cp -a "$DATA_DIR/$name" "$stage/$name"
    fi
  done
  if [[ -f "$ENV_FILE" ]]; then
    cp -a "$ENV_FILE" "$stage/env/rubika-copier.env"
  fi
  if [[ -f "$UNIT_DEST" ]]; then
    cp -a "$UNIT_DEST" "$stage/unit/rubika-copier.service"
  elif [[ -f "$APP_DIR/systemd/rubika-copier.service" ]]; then
    cp -a "$APP_DIR/systemd/rubika-copier.service" "$stage/unit/rubika-copier.service"
  fi
  if [[ -d "$DATA_DIR/profiles" ]]; then
    cp -a "$DATA_DIR/profiles/." "$stage/profiles/"
  fi
  archive="$dest/rubika-backup.tar.gz"
  tar -C "$stage" -czf "$archive" .
  rm -rf "$stage"
  (
    cd "$dest"
    sha256sum rubika-backup.tar.gz > rubika-backup.tar.gz.sha256
  )
  chmod 600 "$archive" "$archive.sha256"
  say "پشتیبان: $archive"
}

cmd_backup() {
  local was_active=0
  require_root
  say "پشتیبان‌گیری."
  if [[ "$(svc is-active "$SERVICE_NAME" || true)" == active ]]; then
    was_active=1
    stop_service
  fi
  cmd_backup_body >/dev/null
  if [[ "$was_active" -eq 1 ]]; then
    start_service
    say "سرویس دوباره بالا آمد."
  fi
}

cmd_restore() {
  local archive sumfile tmp name
  require_root
  archive="$RESTORE_FILE"
  if [[ ! -f "$archive" ]]; then
    die "فایل پشتیبان پیدا نشد: $archive"
  fi
  sumfile="${archive}.sha256"
  if [[ ! -f "$sumfile" ]]; then
    die "فایل SHA256 کنار پشتیبان نیست: $sumfile"
  fi
  if ! (cd "$(dirname "$archive")" && sha256sum -c "$(basename "$sumfile")"); then
    die "SHA256 پشتیبان جور نیست. بازیابی انجام نشد"
  fi
  say "امضای پشتیبان درست است. بازیابی شروع شد."
  stop_service
  tmp="$(mktemp -d)"
  tar -C "$tmp" -xzf "$archive"
  mkdir -p "$DATA_DIR" "$(dirname "$ENV_FILE")" "$(dirname "$UNIT_DEST")"
  for name in copier.db copier.db-wal copier.db-shm registry.db registry.db-wal registry.db-shm whatsapp.db whatsapp.db-wal whatsapp.db-shm; do
    if [[ -f "$tmp/$name" ]]; then
      cp -a "$tmp/$name" "$DATA_DIR/$name"
    fi
  done
  if [[ -f "$tmp/env/rubika-copier.env" ]]; then
    cp -a "$tmp/env/rubika-copier.env" "$ENV_FILE"
    chmod 600 "$ENV_FILE"
  fi
  if [[ -f "$tmp/unit/rubika-copier.service" ]]; then
    cp -a "$tmp/unit/rubika-copier.service" "$UNIT_DEST"
    chmod 644 "$UNIT_DEST"
  fi
  if [[ -d "$tmp/profiles" ]]; then
    rm -rf "$DATA_DIR/profiles"
    mkdir -p "$DATA_DIR/profiles"
    cp -a "$tmp/profiles/." "$DATA_DIR/profiles/"
  fi
  rm -rf "$tmp"
  clear_singleton_locks
  if ! is_test; then
    chown -R rubikacopier:rubikacopier "$DATA_DIR"
  fi
  start_service
  say "بازیابی تمام شد و سرویس بالا آمد."
}

cmd_status() {
  local state enabled mem_kb swap_kb mem_mb swap_mb
  load_port
  state="$(svc is-active "$SERVICE_NAME" || true)"
  enabled="$(svc is-enabled "$SERVICE_NAME" || true)"
  mem_kb="$(awk '/MemTotal:/ {print $2}' /proc/meminfo)"
  swap_kb="$(awk '/SwapTotal:/ {print $2}' /proc/meminfo)"
  mem_mb=$((mem_kb / 1024))
  swap_mb=$((swap_kb / 1024))
  say "سرویس: ${state} (فعال‌سازی: ${enabled})"
  say "حافظه: ${mem_mb} مگابایت، سواپ: ${swap_mb} مگابایت"
  python3 - "$DATA_DIR/copier.db" <<'PY' | tee -a "$LOG"
import os
import sqlite3
import sys
path = sys.argv[1]
labels = ("queued", "retry", "sending", "sent", "failed", "skipped")
if not os.path.exists(path):
    print("صف: پایگاه هنوز ساخته نشده")
    raise SystemExit(0)
uri = "file:" + path + "?mode=ro"
con = sqlite3.connect(uri, uri=True)
con.execute("PRAGMA query_only=ON")
try:
    rows = dict(con.execute("SELECT status, COUNT(*) FROM posts GROUP BY status"))
except sqlite3.Error as exc:
    print("صف: خواندن پایگاه ناموفق بود")
    print(exc)
    raise SystemExit(0)
parts = [f"{name}={int(rows.get(name, 0))}" for name in labels]
print("صف: " + " ".join(parts))
PY
  python3 - "$CREDS_FILE" "$PORT" <<'PY' | tee -a "$LOG"
import json
import os
import sys
import urllib.error
import urllib.request
creds, port = sys.argv[1], sys.argv[2]
user = password = ""
if os.path.exists(creds):
    for raw in open(creds, encoding="utf-8"):
        if "=" not in raw:
            continue
        name, value = raw.rstrip("\n").split("=", 1)
        if name == "user":
            user = value
        elif name == "password":
            password = value

def unknown():
    print("نشست تلگرام: نامشخص")
    print("نشست روبیکا: نامشخص")

if not user:
    unknown()
    raise SystemExit(0)
body = json.dumps({"username": user, "password": password}).encode()
base = f"http://127.0.0.1:{port}"
try:
    opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor())
    request = urllib.request.Request(base + "/api/session", data=body, headers={"Content-Type": "application/json"})
    opener.open(request, timeout=4).read()
    status = json.loads(opener.open(base + "/api/status", timeout=4).read().decode())
except (OSError, urllib.error.URLError, json.JSONDecodeError, TimeoutError):
    unknown()
    raise SystemExit(0)
session = status.get("session") or {}
for name, label in (("telegram", "تلگرام"), ("rubika", "روبیکا")):
    state = (session.get(name) or {}).get("state") or "unknown"
    ready = "آماده" if state == "ready" else state
    print(f"نشست {label}: {ready}")
PY
}

cmd_info() {
  local lines url user password
  if [[ ! -f "$CREDS_FILE" ]]; then
    die "فایل اعتبار پیدا نشد. اول نصب کنید"
  fi
  mapfile -t lines < <(read_credentials)
  url="${lines[0]:-}"
  user="${lines[1]:-}"
  password="${lines[2]:-}"
  local state
  state="$(svc is-active "$SERVICE_NAME" || true)"
  printf 'پنل: %s\n' "$url"
  printf 'نام کاربری: %s\n' "$user"
  printf 'رمز: %s\n' "$password"
  say "سرویس: ${state}"
  say "فایل اعتبار: ${CREDS_FILE}"
}

confirm_purge() {
  local typed=""
  if is_test && [[ -n "${RUBIKA_INSTALL_PURGE_CONFIRM:-}" ]]; then
    typed="$RUBIKA_INSTALL_PURGE_CONFIRM"
  else
    printf '%s\n' "برای پاک کردن داده این عبارت را بنویسید: حذف داده"
    read -r typed || typed=""
  fi
  if [[ "$typed" != "حذف داده" ]]; then
    die "تأیید نوشته نشد. هیچ داده‌ای پاک نشد"
  fi
}

cmd_uninstall() {
  require_root
  say "حذف سرویس و کد."
  stop_service
  svc disable "$SERVICE_NAME" || true
  rm -f "$UNIT_DEST"
  svc daemon-reload || true
  rm -rf "$APP_DIR"
  if [[ "$PURGE" -eq 1 ]]; then
    confirm_purge
    rm -rf "$DATA_DIR" "$ENV_FILE" "$CREDS_FILE"
    say "داده، env و فایل اعتبار هم پاک شد. پشتیبان‌ها در ${BACKUP_ROOT} ماندند."
  else
    say "داده در ${DATA_DIR} ماند. env و فایل اعتبار هم ماندند."
  fi
  say "حذف تمام شد."
}

cmd_reset() {
  require_root
  if ! installed_marker; then
    die "نصبی پیدا نشد. اول نصب کنید"
  fi
  resolve_identity
  prompt_reset
  if [[ -z "$PANEL_PASS" ]]; then
    PANEL_PASS="$(python3 -c 'import secrets; print(secrets.token_urlsafe(18))')"
    GENERATED_PASS=1
  fi
  write_env
  write_credentials
  start_service
  say "ورود پنل عوض شد و سرویس دوباره بالا آمد."
}

cmd_menu() {
  cat <<'EOF'
روبیکا کپی‌یار
۱) نصب
۲) به‌روزرسانی
۳) پشتیبان
۴) بازیابی
۵) وضعیت
۶) اطلاعات ورود
۷) بازنشانی نام کاربری و رمز
۸) حذف
۰) خروج
EOF
  local choice answer
  read -r -p "شماره را بنویسید: " choice || die "ورودی خوانده نشد"
  case "$choice" in
    1) cmd_install ;;
    2) cmd_update ;;
    3) cmd_backup ;;
    4)
      read -r -p "مسیر فایل tar.gz: " RESTORE_FILE || die "ورودی خوانده نشد"
      cmd_restore
      ;;
    5) cmd_status ;;
    6) cmd_info ;;
    7)
      ACTION=reset
      cmd_reset
      ;;
    8)
      read -r -p "داده هم پاک شود؟ بله/خیر: " answer || answer="خیر"
      if [[ "$answer" == "بله" ]]; then
        PURGE=1
      fi
      cmd_uninstall
      ;;
    0) exit 0 ;;
    *) die "گزینه نامعتبر است" ;;
  esac
}

main() {
  parse_args "$@"
  if is_test; then
    apply_test_paths
  fi
  prepare_log
  if [[ "$ACTION" == "" ]]; then
    if [[ ! -t 0 ]]; then
      die "منو ورودی می‌خواهد. برای نصب خودکار: bash rubika-install.sh --install"
    fi
    cmd_menu
    return 0
  fi
  case "$ACTION" in
    install) cmd_install ;;
    update) cmd_update ;;
    backup) cmd_backup ;;
    restore) cmd_restore ;;
    status) cmd_status ;;
    info) cmd_info ;;
    reset) cmd_reset ;;
    uninstall) cmd_uninstall ;;
    *) die "عملیات نامعتبر است" ;;
  esac
}

main "$@"
exit 0
